#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4

# This wizard never writes a .env file, so keep the library away from one.
ENV_FILE=/dev/null

SKILLS_REPO_URL="${SKILLS_REPO_URL:-https://github.com/atendev/skills.git}"
DEFAULT_CLONE_DIR="$HOME/.local/share/atendev-skills"

die() {
  printf '\n  %s✗ %s%s\n\n' "$RED" "$1" "$RESET" >&2
  exit 1
}

# ask_yn VAR "Prompt: " asks until the answer is y/yes or n/no. Pressing Enter
# alone counts as no. Sets VAR to y or n.
ask_yn() {
  local var="$1" prompt="$2" reply="" lower=""
  while true; do
    printf '  %s%s%s' "$BOLD" "$prompt" "$RESET"
    if ! read -r reply; then
      printf '\n'
      die "No more input to read. Run the wizard again."
    fi
    lower=$(printf '%s' "$reply" | tr '[:upper:]' '[:lower:]')
    case "$lower" in
      y | yes) printf -v "$var" '%s' y; return 0 ;;
      "" | n | no) printf -v "$var" '%s' n; return 0 ;;
      *) warn "Please answer y or n, or press Enter for no." ;;
    esac
  done
}

# splash draws the opening screen.
splash() {
  _clear
  local aten=(
    " █████╗ ████████╗███████╗███╗   ██╗"
    "██╔══██╗╚══██╔══╝██╔════╝████╗  ██║"
    "███████║   ██║   █████╗  ██╔██╗ ██║"
    "██╔══██║   ██║   ██╔══╝  ██║╚██╗██║"
    "██║  ██║   ██║   ███████╗██║ ╚████║"
    "╚═╝  ╚═╝   ╚═╝   ╚══════╝╚═╝  ╚═══╝"
  )
  local dev=(
    "██████╗ ███████╗██╗   ██╗"
    "██╔══██╗██╔════╝██║   ██║"
    "██║  ██║█████╗  ██║   ██║"
    "██║  ██║██╔══╝  ╚██╗ ██╔╝"
    "██████╔╝███████╗ ╚████╔╝ "
    "╚═════╝ ╚══════╝  ╚═══╝  "
  )
  local cool=(123 87 51 45 39 33) warm=(226 220 214 208 202 196)
  local r c1 c2 deep=0
  if [[ -n "$BOLD" ]] && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 256 ]]; then deep=1; fi
  printf '\n\n'
  for (( r = 0; r < 6; r++ )); do
    if (( deep )); then
      c1=$(tput setaf "${cool[$r]}"); c2=$(tput setaf "${warm[$r]}")
    else
      c1="$BLUE"; c2="$YELLOW"
    fi
    printf '   %s%s%s%s%s%s%s%s\n' "$BOLD" "$c1" "${aten[$r]}" "$RESET" "$BOLD" "$c2" "${dev[$r]}" "$RESET"
  done
  printf '\n'
  printf '   %sSkills for your AI coding agents%s\n\n' "$BOLD" "$RESET"
  printf '   %sPick skills  →  Pick AI tools  →  Install%s\n\n' "$DIM" "$RESET"
  printf '   %sEvery y/N question defaults to no.%s\n\n' "$DIM" "$RESET"
  pause "Press Enter to begin"
}

# skill_blurb NAME REPO prints the short line for the install list. It reads
# REPO/skills.txt ("name: blurb" per line) and falls back to the SKILL.md text.
skill_blurb() {
  local b=""
  if [[ -f "$2/skills.txt" ]]; then
    b=$(awk -v n="$1" '
      /^[ \t]*#/ { next }
      { sub(/\r$/, "") }
      index($0, n ": ") == 1 { print substr($0, length(n) + 3); exit }
    ' "$2/skills.txt")
  fi
  if [[ -z "$b" ]]; then b=$(skill_desc "$2/skills/$1/SKILL.md"); fi
  printf '%s' "$b"
}

# expand_tilde "~/x" gives "$HOME/x". Other paths pass through.
expand_tilde() {
  case "$1" in
    "~") printf '%s' "$HOME" ;;
    "~/"*) printf '%s' "$HOME${1#\~}" ;;
    *) printf '%s' "$1" ;;
  esac
}

has_skills() {
  local f
  for f in "$1"/skills/*/SKILL.md; do
    [[ -f "$f" ]] && return 0
  done
  return 1
}

# skill_desc FILE prints a short description from the SKILL.md frontmatter.
skill_desc() {
  local d
  d=$(awk '
    { sub(/\r$/, "") }
    NR == 1 { if ($0 != "---") exit; next }
    $0 == "---" { exit }
    block == 1 { if ($0 ~ /^[ \t]+[^ \t]/) { sub(/^[ \t]+/, ""); print } ; exit }
    /^description:/ {
      sub(/^description:[ \t]*/, "")
      if ($0 ~ /^[>|][-+]?[ \t]*$/) { block = 1; next }
      print; exit
    }
  ' "$1")
  d="${d#"${d%%[![:space:]]*}"}"
  d="${d%"${d##*[![:space:]]}"}"
  case "$d" in
    \"*\") d="${d#\"}"; d="${d%\"}" ;;
    \'*\') d="${d#\'}"; d="${d%\'}" ;;
  esac
  d="${d%%. *}"
  d="${d%.}"
  if (( ${#d} > 80 )); then
    d="${d:0:80}"
    d="${d% *}..."
  fi
  [[ -n "$d" ]] || d="(no description)"
  printf '%s' "$d"
}

join_csv() {
  local out="" item
  for item in "$@"; do
    out="${out:+$out,}$item"
  done
  printf '%s' "$out"
}

# short_path "/home/x/y" prints "~/y" for paths under $HOME.
short_path() {
  if [[ "$1" == "$HOME"* ]]; then printf '~%s' "${1#"$HOME"}"; else printf '%s' "$1"; fi
}

# plan_row SYMBOL_COLOR SYMBOL NAME STATUS prints one checklist row.
plan_row() {
  printf '    %s%s%s %-20s %s%s%s\n' "$1" "$2" "$RESET" "$3" "$DIM" "$4" "$RESET"
}

# render_plan "PLAN" turns the link-skills dry-run text into a short checklist.
# It sets PLAN_LINKS and PLAN_NOTES to the counts the script reported.
render_plan() {
  local line rest dest hub="" skip=0 conflicts=0 owns=0
  PLAN_LINKS=0
  PLAN_NOTES=0
  printf '  %s✓%s will be created    %s○%s already in place    %s!%s left alone\n\n' \
    "$GREEN" "$RESET" "$DIM" "$RESET" "$YELLOW" "$RESET"
  while IFS= read -r line; do
    if (( skip )); then
      [[ "$line" == *"link-skills:end -->"* ]] && skip=0
      continue
    fi
    case "$line" in
      "" | "Conflicts and own copies"* | "Dry run"*) ;;
      "Hub: "*) hub="${line#Hub: }"; hub="${hub%% (*}" ;;
      "Add to hub from "*)
        printf '  %sGlobal skills folder%s  %s%s%s\n' "$BOLD" "$RESET" "$DIM" "$(short_path "$hub")" "$RESET" ;;
      "Summary: "*)
        [[ "$line" =~ ([0-9]+)\ to\ link ]] && PLAN_LINKS="${BASH_REMATCH[1]}"
        [[ "$line" =~ ([0-9]+)\ note ]] && PLAN_NOTES="${BASH_REMATCH[1]}"
        [[ "$line" =~ ([0-9]+)\ conflict ]] && conflicts="${BASH_REMATCH[1]}"
        [[ "$line" =~ ([0-9]+)\ own ]] && owns="${BASH_REMATCH[1]}" ;;
      "  "*)
        rest="${line#  }"
        case "$rest" in
          link\ *)
            rest="${rest#link}"; rest="${rest#"${rest%%[![:space:]]*}"}"; dest="${rest%% -> *}"
            plan_row "$GREEN" "✓" "$(basename "$dest")" "new link" ;;
          ok\ *)
            rest="${rest#ok}"; rest="${rest#"${rest%%[![:space:]]*}"}"
            if [[ "$rest" == *" -> "* ]]; then
              plan_row "$DIM" "○" "$(basename "${rest%% -> *}")" "already linked"
            else
              plan_row "$DIM" "○" "$(basename "${rest%% (*}")" "install rule already there"
            fi ;;
          conflict\ *)
            rest="${rest#conflict}"; rest="${rest#"${rest%%[![:space:]]*}"}"
            plan_row "$YELLOW" "!" "$(basename "${rest%% -> *}")" "link points somewhere else, left alone" ;;
          own\ copy\ *)
            rest="${rest#own copy}"; rest="${rest#"${rest%%[![:space:]]*}"}"
            plan_row "$YELLOW" "!" "$(basename "${rest%% -> *}")" "real folder, left alone" ;;
          note\ *)
            rest="${rest#note}"; rest="${rest#"${rest%%[![:space:]]*}"}"
            case "$rest" in
              *"keeps global rules"*)
                printf '    %s›%s %spaste the install rule into %s yourself (shown at the end)%s\n' \
                  "$DIM" "$RESET" "$DIM" "${rest%% keeps global*}" "$RESET"
                skip=1 ;;
              *"will add the install rule"*) plan_row "$GREEN" "✓" "$(basename "${rest%% (*}")" "add the install rule" ;;
              *"will create it"*) plan_row "$GREEN" "✓" "$(basename "${rest%% (*}")" "create it with the install rule" ;;
              *) plan_row "$YELLOW" "!" "$(basename "${rest%% (*}")" "not a regular file, left alone" ;;
            esac ;;
        esac ;;
      *)
        dest="${line#*(}"; dest="${dest%%)*}"
        printf '\n  %s%s%s  %s%s%s\n' "$BOLD" "${line%% (*}" "$RESET" "$DIM" "$(short_path "$dest")" "$RESET" ;;
    esac
  done <<< "$1"
  printf '\n  Will create %s link(s)' "$PLAN_LINKS"
  (( PLAN_NOTES == 0 )) || printf ' and add %s note(s)' "$PLAN_NOTES"
  printf '.'
  if (( conflicts + owns > 0 )); then
    printf ' %s%s left alone.%s' "$YELLOW" "$((conflicts + owns))" "$RESET"
  fi
  printf '\n\n'
}

# skill_intro REPO prints the question and the list of skills.
skill_intro() {
  local n
  say "Which skills would you like to install?"
  say "Available skills:"
  for n in "${SKILL_NAMES[@]}"; do
    printf '  - %s%s%s: %s\n' "$BOLD" "$n" "$RESET" "$(skill_blurb "$n" "$1")"
  done
  printf '\n'
  note "The default answer is no."
  printf '\n'
}

main() {
  local SCRIPT_DIR="" src="${BASH_SOURCE[0]:-}" arg
  local FORCE_SCREENS=0
  [[ -z "${ATENDEV_FORCE_SCREENS:-}" ]] || FORCE_SCREENS=1
  for arg in "$@"; do
    case "$arg" in
      --force-screens) FORCE_SCREENS=1 ;;
      -h | --help)
        printf 'Usage: install.sh [--force-screens]\n\n'
        printf 'Walks you through installing skills and linking them into your AI tools.\n\n'
        printf '  --force-screens   Always show the confirm screen, even when every link\n'
        printf '                    already exists. For testing. Piped installs can set\n'
        printf '                    ATENDEV_FORCE_SCREENS=1 instead.\n'
        exit 0 ;;
      *) die "Unknown option: $arg. Try --help." ;;
    esac
  done

  if [[ -n "$src" && -f "$src" ]]; then
    SCRIPT_DIR="$(cd "$(dirname "$src")" && pwd)"
  elif [[ ! -t 0 ]]; then
    # The script is piped in (curl | bash), so stdin is the script itself.
    # Answers have to come from the terminal.
    if { exec < /dev/tty; } 2>/dev/null; then :; else
      die "No terminal to read answers from. Download the script and run it with bash instead."
    fi
  fi

  splash

  # Find the skills repo. This has no page of its own. It only speaks up when
  # it has to download a copy.
  local REPO_DIR="" INSTALL_DIR=""
  if [[ -n "$SCRIPT_DIR" ]] && has_skills "$SCRIPT_DIR"; then
    REPO_DIR="$SCRIPT_DIR"
  else
    printf '\n'
    say "This script is not inside a checkout of the skills repo."
    say "It will download one."
    printf '\n'
    ask INSTALL_DIR "Folder for the download [$DEFAULT_CLONE_DIR]:"
    [[ -n "$INSTALL_DIR" ]] || INSTALL_DIR="$DEFAULT_CLONE_DIR"
    INSTALL_DIR="$(expand_tilde "$INSTALL_DIR")"
    command -v git >/dev/null 2>&1 || die "git is not installed. Install git and run the wizard again."
    if [[ -d "$INSTALL_DIR/.git" ]]; then
      say "Updating the existing clone in $INSTALL_DIR"
      git -C "$INSTALL_DIR" pull --ff-only || die "git pull failed in $INSTALL_DIR."
    elif [[ -e "$INSTALL_DIR" && -n "$(ls -A "$INSTALL_DIR" 2>/dev/null)" ]]; then
      die "$INSTALL_DIR already exists and is not a clone of the skills repo."
    else
      say "Cloning $SKILLS_REPO_URL into $INSTALL_DIR"
      git clone "$SKILLS_REPO_URL" "$INSTALL_DIR" || die "git clone failed."
    fi
    REPO_DIR="$(cd "$INSTALL_DIR" && pwd)"
    has_skills "$REPO_DIR" || die "No skills found in $REPO_DIR/skills."
    pause "Press Enter to continue"
  fi
  local LINK_SCRIPT="$REPO_DIR/skills/link-skills/scripts/link-skills.sh"
  [[ -f "$LINK_SCRIPT" ]] || die "Missing $LINK_SCRIPT. Is this the skills repo?"

  # ── Stage 1 ──────────────────────────────────────────────────────────────
  stage "Pick skills"
  local SKILL_NAMES=() SKILL_COUNT=0 skill_dir name
  for skill_dir in "$REPO_DIR"/skills/*; do
    [[ -f "$skill_dir/SKILL.md" ]] || continue
    name="$(basename "$skill_dir")"
    SKILL_NAMES[SKILL_COUNT]="$name"
    SKILL_COUNT=$((SKILL_COUNT + 1))
  done
  local i CHOSEN_SKILLS=() CHOSEN_SKILL_COUNT=0 answer
  skill_intro "$REPO_DIR"
  ask_yn answer "Install all skills [y/N]: "
  if [[ "$answer" == "y" ]]; then
    for (( i = 0; i < SKILL_COUNT; i++ )); do
      CHOSEN_SKILLS[CHOSEN_SKILL_COUNT]="${SKILL_NAMES[$i]}"
      CHOSEN_SKILL_COUNT=$((CHOSEN_SKILL_COUNT + 1))
    done
  else
    # Redraw the same page without the install-all question, then ask one by one.
    _STAGE_INDEX=$((_STAGE_INDEX - 1))
    stage "Pick skills"
    skill_intro "$REPO_DIR"
    for (( i = 0; i < SKILL_COUNT; i++ )); do
      ask_yn answer "Install ${SKILL_NAMES[$i]} [y/N]: "
      if [[ "$answer" == "y" ]]; then
        CHOSEN_SKILLS[CHOSEN_SKILL_COUNT]="${SKILL_NAMES[$i]}"
        CHOSEN_SKILL_COUNT=$((CHOSEN_SKILL_COUNT + 1))
      fi
    done
  fi
  if (( CHOSEN_SKILL_COUNT == 0 )); then
    printf '\n'
    say "You did not pick any skills. Nothing to install."
    printf '\n'
    exit 0
  fi
  local ONLY_CSV
  ONLY_CSV="$(join_csv "${CHOSEN_SKILLS[@]}")"

  # ── Stage 2 ──────────────────────────────────────────────────────────────
  stage "Pick AI tools"
  local TOOL_NAMES=() TOOL_DISPLAY=() TOOL_PATHS=() TOOL_COUNT=0 line tname tdisp tpath
  local tools_out
  tools_out="$(bash "$LINK_SCRIPT" --list-tools)" || die "Could not detect AI tools."
  while IFS=$'\t' read -r tname tdisp tpath; do
    [[ -n "$tname" ]] || continue
    TOOL_NAMES[TOOL_COUNT]="$tname"
    TOOL_DISPLAY[TOOL_COUNT]="$tdisp"
    TOOL_PATHS[TOOL_COUNT]="$tpath"
    TOOL_COUNT=$((TOOL_COUNT + 1))
  done <<< "$tools_out"

  local CHOSEN_AI=() CHOSEN_AI_NAMES=() CHOSEN_AI_COUNT=0
  local EXTRA_DIRS=() EXTRA_COUNT=0 extra
  if (( TOOL_COUNT == 0 )); then
    say "No AI tools detected."
    printf '\n'
    ask extra "Skills folder to link into (leave empty to skip):"
    extra="$(expand_tilde "$extra")"
    if [[ -n "$extra" ]]; then
      EXTRA_DIRS[EXTRA_COUNT]="$extra"
      EXTRA_COUNT=$((EXTRA_COUNT + 1))
    fi
  else
    say "Detected AI tools:"
    for (( i = 0; i < TOOL_COUNT; i++ )); do
      say "- ${TOOL_DISPLAY[$i]}: ${TOOL_PATHS[$i]}"
    done
    printf '\n'
    note "The default answer is no."
    printf '\n'
    for (( i = 0; i < TOOL_COUNT; i++ )); do
      ask_yn answer "Link ${TOOL_DISPLAY[$i]} [y/N]: "
      if [[ "$answer" == "y" ]]; then
        CHOSEN_AI[CHOSEN_AI_COUNT]="${TOOL_NAMES[$i]}"
        CHOSEN_AI_NAMES[CHOSEN_AI_COUNT]="${TOOL_DISPLAY[$i]}"
        CHOSEN_AI_COUNT=$((CHOSEN_AI_COUNT + 1))
      fi
    done
  fi
  while true; do
    ask_yn answer "Add another skills folder (for example ./.claude/skills in a project)? [y/N] "
    [[ "$answer" == "y" ]] || break
    ask extra "Skills folder:"
    extra="$(expand_tilde "$extra")"
    if [[ -z "$extra" ]]; then
      warn "No folder entered."
    elif [[ "$extra" == -* ]]; then
      warn "A folder name cannot start with a dash. Try ./$extra instead."
    else
      EXTRA_DIRS[EXTRA_COUNT]="$extra"
      EXTRA_COUNT=$((EXTRA_COUNT + 1))
    fi
  done
  if (( CHOSEN_AI_COUNT == 0 && EXTRA_COUNT == 0 )); then
    printf '\n'
    say "You did not pick any tools or folders. Nothing to link."
    printf '\n'
    exit 0
  fi

  # ── Stage 3 ──────────────────────────────────────────────────────────────
  stage "Confirm and install"
  local AI_ARG="none"
  (( CHOSEN_AI_COUNT == 0 )) || AI_ARG="$(join_csv "${CHOSEN_AI[@]}")"
  local CMD=(bash "$LINK_SCRIPT" --from "$REPO_DIR/skills" --only "$ONLY_CSV" --ai "$AI_ARG")
  for (( i = 0; i < EXTRA_COUNT; i++ )); do
    CMD[${#CMD[@]}]="--tool-dir"
    CMD[${#CMD[@]}]="${EXTRA_DIRS[$i]}"
  done
  say "Here is what will happen. Nothing has changed yet."
  printf '\n'
  local plan run_out
  plan="$("${CMD[@]}" --dry-run)" || die "The plan failed. See the message above."
  render_plan "$plan"
  if (( PLAN_LINKS == 0 && PLAN_NOTES == 0 && FORCE_SCREENS == 0 )); then
    say "Everything you picked is already in place. Nothing to change."
    printf '\n'
    run_out="$plan"
  else
    if ! confirm "Go ahead and make these changes?"; then
      printf '\n'
      say "Stopped. Nothing was changed."
      printf '\n'
      exit 0
    fi
    run_out="$("${CMD[@]}" --yes)" || { printf '%s\n' "$run_out"; die "link-skills.sh failed. See the output above."; }
  fi

  # ── Stage 4 ──────────────────────────────────────────────────────────────
  stage "Summary"
  printf '\n'
  local created
  created="$(printf '%s\n' "$run_out" | grep -E '^(Created [0-9]+ link|Nothing to link)' || true)"
  say "${created:-Nothing to link.}"
  local linked left
  linked="$(printf '%s\n' "$run_out" | awk '
    /^  link / {
      d = $0; sub(/^  link +/, "", d); sub(/ -> .*/, "", d); sub(/\/[^\/]*$/, "", d)
      if (!(d in n)) order[++k] = d
      n[d]++
    }
    END { for (j = 1; j <= k; j++) printf "  - %d new link(s) in %s\n", n[order[j]], order[j] }
  ')"
  if [[ -n "$linked" ]]; then
    printf '\n'
    say "Linked:"
    printf '%s\n' "$linked"
  fi
  local rule_added rule_paste
  rule_added="$(printf '%s\n' "$run_out" | grep -E '^Added the install rule' || true)"
  rule_paste="$(printf '%s\n' "$run_out" | awk '
    /^  note .* keeps global rules somewhere/ { n = $0; sub(/^  note +/, "", n); sub(/ keeps global rules.*/, "", n); print "  - " n }
  ')"
  if [[ -n "$rule_added" ]]; then
    printf '\n'
    say "$rule_added"
    say "It tells agents to put new skills in the hub and then run link-skills."
  fi
  if [[ -n "$rule_paste" ]]; then
    printf '\n'
    say "These tools keep global rules where this script cannot edit. Paste this install rule into them yourself:"
    printf '%s\n' "$rule_paste"
    printf '\n'
    printf '%s\n' "$run_out" | awk '/<!-- link-skills:start -->/ { p = 1 } p { print } /<!-- link-skills:end -->/ { exit }'
  fi
  left="$(printf '%s\n' "$run_out" | grep -E '^  (conflict|own copy) |^  note .*left alone' || true)"
  if [[ -n "$left" ]]; then
    printf '\n'
    warn "Left alone, because something is already there:"
    printf '%s\n' "$left"
    note "Move or remove those by hand if you want them linked, then run this again."
  fi
  printf '\n'
  say "Restart these so they pick up the skills:"
  for (( i = 0; i < CHOSEN_AI_COUNT; i++ )); do
    say "- ${CHOSEN_AI_NAMES[$i]}"
  done
  for (( i = 0; i < EXTRA_COUNT; i++ )); do
    say "- any tool that reads ${EXTRA_DIRS[$i]}"
  done
  printf '\n'
  say "To add more skills later, run the link-skills skill, or run:"
  say "$LINK_SCRIPT"
  printf '\n'
  printf '  %s✓ Done%s\n\n' "$GREEN" "$RESET"
}

main "$@"; exit $?
